// Original fixed 2D view rendered from our procedural js/kit-3d.js model.
// Base artwork and visibility masks are generated by qa/generate-kit-art.mjs.
// No WebGL or Three.js is needed to display this view or animate its hits.
import { INSTRUMENTS, INST } from './patterns.js';
import { KIT_ART } from './kit-art-data.js';

const NS = 'http://www.w3.org/2000/svg';
const LABELS = { kick: 'Kick', tom1: 'Tom 1', tom2: 'Tom 2', snare: 'Dobos', tom3: 'Floor tom', hhpedal: 'HH nogom', hihat: 'Hi-hat', crash: 'Crash', ride: 'Ride', crash2: 'Crash 2' };
const HIT_COLORS = { good: '#1e8e3e', ok: '#9a9a9a', extra: '#d93025', miss: '#d93025', free: '#111' };
let nextKit = 0;
function el(tag, attrs, parent) {
  const node = document.createElementNS(NS, tag);
  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, value);
  parent?.appendChild(node); return node;
}
export function createKit(container) {
  container.replaceChildren();
  const { width, height, pads } = KIT_ART, prefix = `kit-art-${++nextKit}`;
  const svg = el('svg', { viewBox: `0 0 ${width} ${height}`, class: 'kit-svg', role: 'img', 'aria-label': 'Bubanj', preserveAspectRatio: 'xMidYMid meet' }, container);
  el('title', {}, svg).textContent = '2D crtež iz našeg 3D modela';
  const defs = el('defs', {}, svg);
  el('image', { href: 'assets/kit/drummer-2d.png', width, height, 'data-kit-art': '' }, svg);
  const fx = el('g', { class: 'fx' }, svg), labels = el('g', { class: 'labels' }, svg), targets = {};
  for (const [id, pad] of Object.entries(pads)) {
    // The masks share the model's camera and depth buffer, so color cannot
    // leak through a drum, stand or cymbal in front of the struck surface.
    const mask = el('mask', { id: `${prefix}-${id}`, maskUnits: 'userSpaceOnUse', x: 0, y: 0, width, height, 'mask-type': 'luminance' }, defs);
    el('image', { href: `assets/kit/mask-${id}.png`, width, height }, mask);
    const overlay = el('rect', { x: 0, y: 0, width, height, mask: `url(#${prefix}-${id})`, class: 'overlay', opacity: 0, 'data-pad': id }, fx);
    const hit = el('polygon', { points: pad.outline.map(p => p.join(',')).join(' '), class: 'hitring', opacity: 0, 'data-pad': id }, fx);
    targets[id] = { overlay, hit };
  }
  const keysByTarget = {};
  for (const inst of INSTRUMENTS) (keysByTarget[inst.target] ||= []).push(...inst.keys.map(k => k.replace('Key', '')));
  for (const [id, label] of Object.entries(LABELS)) {
    const { center, outline } = pads[id];
    const y = id === 'hhpedal' ? Math.max(...outline.map(p => p[1])) + 30 : center[1] + (Math.max(...outline.map(p => p[1])) - Math.min(...outline.map(p => p[1]))) * .34;
    el('text', { x: center[0], y, class: 'padlabel' }, labels).textContent = label;
    el('text', { x: center[0], y: y + 23, class: 'keyhint' }, labels).textContent = [...new Set(keysByTarget[id] || [])].join(' ');
  }
  el('rect', { x: 50, y: height - 225, width: 10, height: 140, rx: 5, class: 'meterbg' }, svg);
  const meter = el('rect', { x: 50, y: height - 85, width: 10, height: 0, rx: 5, class: 'ink' }, svg);
  const openLabel = el('text', { x: pads.hihat.center[0], y: pads.hihat.center[1] - 25, class: 'openlabel', opacity: 0 }, svg);
  openLabel.textContent = 'OTVOREN';
  function fade(node, from, duration = 380) {
    for (const animation of node.getAnimations()) animation.cancel();
    node.animate([{ opacity: from }, { opacity: 0 }], { duration, easing: 'cubic-bezier(.2,.7,.3,1)' });
  }
  function colorPad(target, instrument) { target.overlay.style.fill = instrument.color; fade(target.overlay, .88); }
  return {
    pulse(id) {
      const instrument = INST[id], target = instrument && targets[instrument.target]; if (!target) return;
      colorPad(target, instrument); if (id === 'hho') fade(openLabel, 1, 500);
    },
    hit(id, kind) {
      const instrument = INST[id], target = instrument && targets[instrument.target]; if (!target) return;
      if (kind !== 'miss') colorPad(target, instrument);
      target.hit.setAttribute('stroke', HIT_COLORS[kind] || HIT_COLORS.free);
      fade(target.hit, kind === 'miss' ? .6 : 1, kind === 'miss' ? 300 : 420);
    },
    pedal(v) {
      const value = Math.max(0, Math.min(127, Number(v) || 0)) / 127 * 140;
      meter.setAttribute('y', height - 85 - value); meter.setAttribute('height', value);
    },
  };
}
